99	void sync_file(const fs::path& path)
100	{
101	#ifdef _WIN32
102	    HANDLE handle = CreateFileW(path.wstring().c_str(), GENERIC_WRITE, FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE,
103	                                nullptr, OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, nullptr);
104	    require(handle != INVALID_HANDLE_VALUE, "cannot open for flush: " + path.string());
105	    const BOOL ok = FlushFileBuffers(handle);
106	    CloseHandle(handle);
107	    require(ok != 0, "cannot flush " + path.string());
108	#else
109	    const int fd = ::open(path.c_str(), O_RDONLY);
110	    require(fd >= 0, "cannot open for sync: " + path.string());
111	#ifdef __APPLE__
112	    const bool ok = ::fcntl(fd, F_FULLFSYNC) == 0 || ::fsync(fd) == 0;
113	#else
114	    const bool ok = ::fsync(fd) == 0;
115	#endif
116	    ::close(fd);
117	    require(ok, "cannot sync " + path.string());
118	#endif
119	}
