121	void sync_directory(const fs::path& path)
122	{
123	#ifdef _WIN32
124	    // Win32 FlushFileBuffers is documented for writable file/volume handles,
125	    // not directory handles. Files are flushed individually and publication
126	    // uses MOVEFILE_WRITE_THROUGH. A volume flush would require admin rights.
127	    (void)path;
128	#else
129	    const int fd = ::open(path.c_str(), O_RDONLY | O_DIRECTORY);
130	    require(fd >= 0, "cannot open directory for sync: " + path.string());
131	    const bool ok = ::fsync(fd) == 0;
132	    ::close(fd);
133	    require(ok, "cannot sync directory " + path.string());
134	#endif
135	}
