137	void checked_write(const fs::path& path, const std::string& content)
138	{
139	    std::ofstream out(path, std::ios::binary | std::ios::trunc);
140	    require(out.is_open(), "cannot create " + path.string());
141	    out.write(content.data(), static_cast<std::streamsize>(content.size()));
142	    out.flush();
143	    require(out.good(), "cannot write " + path.string());
144	    out.close();
145	    require(!out.fail(), "cannot close " + path.string());
146	    sync_file(path);
147	}
