443	void ProjectVersionStore::recover_uncommitted()
444	{
445	    const std::set<std::string> committed(m_committed_ids.begin(), m_committed_ids.end());
446	    // The lock proves no earlier process can still be loading from these
447	    // disposable directories. Orca never uses the retained store as backup.
448	    for (const auto& entry : fs::directory_iterator(m_root / "materialized"))
449	        fs::remove_all(entry.path());
450	    for (const auto& entry : fs::directory_iterator(m_root / "pending"))
451	        fs::remove_all(entry.path());
452	    for (const auto& entry : fs::directory_iterator(m_root / "versions"))
453	        if (entry.is_directory() && !committed.count(entry.path().filename().string()))
454	            fs::remove_all(entry.path());
455	    std::set<std::string> reachable;
456	    for (const Version& version : history())
457	        for (const ObjectResource& object : version.objects)
458	            reachable.insert(object.resource.id);
459	    for (const auto& entry : fs::directory_iterator(m_root / "resources"))
460	        if (entry.is_regular_file() && !reachable.count(entry.path().stem().string()))
461	            fs::remove(entry.path());
462	    fs::remove(m_root / "HEAD.pending");
463	    fs::remove(m_root / "current-state.pending");
464	    fs::remove(m_root / "pins.pending");
465	    fs::remove(m_root / "chat-restore.writing.json");
466	    for (const auto& entry : fs::directory_iterator(m_root / "operations"))
467	        if (entry.path().extension() == ".pending")
468	            fs::remove(entry.path());
469	    sync_directory(m_root / "materialized");
470	    sync_directory(m_root / "pending");
471	    sync_directory(m_root / "versions");
472	    sync_directory(m_root / "resources");
473	    sync_directory(m_root / "operations");
474	    sync_directory(m_root);
475	}
