489	void ProjectVersionStore::create_on_first_write()
490	{
491	    if (locked())
492	        return;
493	    create_and_lock();
494	    // This store opened before anything was saved, so it loaded no history.
495	    // Another instance with the same project identity may have saved since.
496	    if (fs::exists(m_root / "HEAD") || fs::exists(m_root / "current-state.json")) {
497	        unlock();
498	        throw std::runtime_error("project was saved by another JusPrin instance");
499	    }
