511	void ProjectVersionStore::lock()
512	{
513	    const fs::path path = m_root / "lock";
514	#ifdef _WIN32
515	    HANDLE handle = CreateFileW(path.wstring().c_str(), GENERIC_READ | GENERIC_WRITE, FILE_SHARE_READ | FILE_SHARE_WRITE,
516	                                nullptr, OPEN_ALWAYS, FILE_ATTRIBUTE_NORMAL, nullptr);
517	    require(handle != INVALID_HANDLE_VALUE, "cannot open project lock");
518	    OVERLAPPED overlap{};
519	    if (LockFileEx(handle, LOCKFILE_EXCLUSIVE_LOCK | LOCKFILE_FAIL_IMMEDIATELY, 0, 1, 0, &overlap) == 0) {
520	        CloseHandle(handle);
521	        throw std::runtime_error("project is open in another JusPrin instance");
522	    }
523	    m_lock_handle = handle;
524	#else
525	    m_lock_fd = ::open(path.c_str(), O_CREAT | O_RDWR, 0600);
526	    require(m_lock_fd >= 0, "cannot open project lock");
527	    if (::flock(m_lock_fd, LOCK_EX | LOCK_NB) != 0) {
528	        ::close(m_lock_fd);
529	        m_lock_fd = -1;
530	        throw std::runtime_error("project is open in another JusPrin instance");
531	    }
532	#endif
533	}
