535	void ProjectVersionStore::unlock()
536	{
537	#ifdef _WIN32
538	    if (m_lock_handle != nullptr) {
539	        OVERLAPPED overlap{};
540	        UnlockFileEx(static_cast<HANDLE>(m_lock_handle), 0, 1, 0, &overlap);
541	        CloseHandle(static_cast<HANDLE>(m_lock_handle));
542	        m_lock_handle = nullptr;
543	    }
544	#else
545	    if (m_lock_fd >= 0) {
546	        ::flock(m_lock_fd, LOCK_UN);
547	        ::close(m_lock_fd);
548	        m_lock_fd = -1;
549	    }
550	#endif
551	}
