553	std::string ProjectVersionStore::new_id()
554	{
555	    static std::mt19937_64 random(std::random_device{}());
556	    static std::mutex random_mutex;
557	    const std::lock_guard<std::mutex> guard(random_mutex);
558	    const auto millis = std::chrono::duration_cast<std::chrono::milliseconds>(
559	        std::chrono::system_clock::now().time_since_epoch()).count();
560	    std::ostringstream id;
561	    id << millis << '-' << std::hex << std::setw(16) << std::setfill('0') << random();
562	    return id.str();
