596	void ProjectVersionStore::load_head()
597	{
598	    if (fs::exists(m_root / "HEAD")) {
599	        const json value = json::parse(read_file(m_root / "HEAD"));
600	        require(value.is_object() && value.value("schema", 0) == 1 && value.contains("versions") &&
601	                value["versions"].is_array(), "unsupported current-version index");
602	        m_head_id = value.at("current").get<std::string>();
603	        std::set<std::string> seen;
604	        for (const json& item : value["versions"]) {
605	            const std::string id = item.get<std::string>();
606	            require(safe_component(id) && seen.insert(id).second, "invalid committed-version index");
607	            m_committed_ids.push_back(id);
608	        }
609	        require(!m_committed_ids.empty() && m_committed_ids.back() == m_head_id,
610	                "current version does not match committed-version index");
611	        require(safe_component(m_head_id), "invalid current version id");
612	        const Version version = read_version(m_head_id);
613	        m_last_metadata_digest = archive_digest(version_dir(m_head_id) / "metadata.3mf");
614	        m_last_regions = version.regions;
615	        for (const ObjectResource& object : version.objects)
616	            m_last_resources[object.object_id] = object;
617	    }
618	    if (fs::exists(m_root / "current-state.json")) {
619	        const json current = json::parse(read_file(m_root / "current-state.json"));
620	        require(current.is_object() && current.value("schema", 0) == 2 && current.contains("state") &&
621	                current["state"].is_object() && current["state"].contains("project") &&
622	                current["state"]["project"].is_object(), "current project document index is invalid");
623	        require(current["state"]["project"].value("projectId", std::string()) == m_project_id,
624	                "current project document does not match the project");
625	        m_last_semantic_state = current["state"].dump(2);
626	        m_document_durable = true;
627	    }
628	    if (!m_head_id.empty())
629	        require(!m_last_semantic_state.empty(), "current project document is missing");
630	    if (!m_last_semantic_state.empty())
631	        validate_attachments(m_root, m_last_semantic_state);
632	}
