634	void ProjectVersionStore::seed_from_live(Model& live)
635	{
636	    if (m_head_id.empty())
637	        return;
638	    const Version version = read_version(m_head_id);
639	    if (version.objects.size() != live.objects.size())
640	        return;
641	    std::map<std::uint64_t, ObjectResource> resources;
642	    std::map<std::uint64_t, std::string> signatures;
643	    for (ModelObject* object : live.objects) {
644	        const int backup_id = live.get_object_backup_id(*object);
645	        const auto found = std::find_if(version.objects.begin(), version.objects.end(), [backup_id](const ObjectResource& item) {
646	            return item.backup_id == backup_id;
647	        });
648	        if (found == version.objects.end() || resources.count(object->id().id))
649	            return;
650	        resources[object->id().id] = *found;
651	        signatures[object->id().id] = signature_of(*object, backup_id);
652	    }
653	    m_last_resources = std::move(resources);
654	    m_last_signatures = std::move(signatures);
655	    m_last_model = std::make_shared<Model>(live);
656	}
657	
658	ProjectVersionStore::Capture ProjectVersionStore::freeze(Model& live, const std::string& version_id,
659	                                                          std::uint64_t revision, std::string semantic_state,
660	                                                          std::string source_path, std::string created_at)
661	{
662	    require(safe_component(version_id), "invalid version id");
663	    const fs::path pending = m_root / "pending" / version_id;
664	    require(fs::exists(pending / "metadata.3mf"), "project metadata was not captured");
665	    require(valid_zip_entry(pending / "metadata.3mf", ""), "project metadata archive is invalid");
666	    json regions = json::parse(semantic_state).value("regions", json::array());
667	    require(regions.is_array(), "project document regions are not a list");
668	    publish_document(std::move(semantic_state));
669	    Capture capture;
670	    capture.version = {version_id, revision, 0, std::move(created_at), std::move(source_path), {}};
671	    capture.version.regions = std::move(regions);
672	    capture.pending_dir = pending;
673	    capture.frozen = std::make_shared<Model>(live);
674	    for (std::size_t index = 0; index < live.objects.size(); ++index) {
675	        ModelObject& original = *live.objects[index];
676	        ModelObject& object = *capture.frozen->objects[index];
677	        const int backup_id = live.get_object_backup_id(original);
678	        capture.frozen->set_object_backup_id(object, backup_id);
679	        ObjectResource item;
680	        item.object_id = object.id().id;
681	        item.backup_id = backup_id;
682	        for (const ModelVolume* volume : object.volumes)
683	            item.facets += volume->mesh().facets_count();
684	        item.entry = entry_for(object);
685	        const std::string signature = signature_of(object, backup_id);
686	        capture.signatures[item.object_id] = signature;
687	        const auto previous = m_last_resources.find(item.object_id);
688	        const auto old_signature = m_last_signatures.find(item.object_id);
689	        if (previous != m_last_resources.end() && old_signature != m_last_signatures.end() &&
690	            old_signature->second == signature) {
691	            item.resource = previous->second.resource;
692	        } else {
693	            item.resource = {new_id(), item.entry};
694	            capture.changed_objects.push_back(item.object_id);
695	        }
696	        capture.version.objects.push_back(std::move(item));
697	    }
698	    validate_metadata(pending / "metadata.3mf", capture.version);
699	    return capture;
700	}
