714	
715	void ProjectVersionStore::publish(Capture capture)
716	{
717	    require(capture.frozen != nullptr, "capture has no model");
718	    require(m_document_durable, "project document must be durable before a model checkpoint");
719	    const fs::path pending = capture.pending_dir;
720	    validate_metadata(pending / "metadata.3mf", capture.version);
721	    fs::create_directories(pending / "new-resources");
722	    Model subset(*capture.frozen);
723	    for (std::size_t index = subset.objects.size(); index > 0; --index)
724	        if (std::find(capture.changed_objects.begin(), capture.changed_objects.end(),
725	                      subset.objects[index - 1]->id().id) == capture.changed_objects.end())
726	            subset.delete_object(index - 1);
727	    subset.set_backup_path((pending / "writer-private").u8string());
728	    if (!subset.objects.empty()) {
729	        const fs::path changed_file = pending / "changed.3mf";
730	        const std::string changed_path = changed_file.u8string();
731	        StoreParams params;
732	        params.path = changed_path.c_str();
733	        params.model = &subset;
734	        params.config = nullptr;
735	        params.strategy = SaveStrategy::Silence | SaveStrategy::SplitModel | SaveStrategy::SkipAuxiliary | SaveStrategy::Zip64;
736	        require(store_bbs_3mf(params), "changed-object serialization failed");
737	        require(valid_zip_entry(changed_path, ""), "changed-object archive is invalid");
738	        mz_zip_archive input;
739	        mz_zip_zero_struct(&input);
740	        require(open_zip_reader(&input, changed_path), "cannot open changed-object archive");
741	        for (ObjectResource& object : capture.version.objects) {
742	            if (std::find(capture.changed_objects.begin(), capture.changed_objects.end(), object.object_id) ==
743	                capture.changed_objects.end())
744	                continue;
745	            const auto subset_object = std::find_if(subset.objects.begin(), subset.objects.end(), [&object](const ModelObject* item) {
746	                return item->id().id == object.object_id;
747	            });
748	            require(subset_object != subset.objects.end(), "changed object was omitted from the serializer input");
749	            object.resource.entry = entry_for(**subset_object);
750	            const int entry_index = mz_zip_reader_locate_file(&input, object.resource.entry.c_str(), nullptr, 0);
751	            require(entry_index >= 0, "serialized object resource is missing: " + object.resource.entry);
752	            const fs::path target = pending / "new-resources" / (object.resource.id + ".zip");
753	            mz_zip_archive output;
754	            mz_zip_zero_struct(&output);
755	            require(open_zip_writer(&output, target.u8string()), "cannot create object resource");
756	            const bool written = mz_zip_writer_add_from_zip_reader(&output, &input, entry_index) &&
757	                                 mz_zip_writer_finalize_archive(&output);
758	            close_zip_writer(&output);
759	            require(written, "object resource write is incomplete: " + object.entry);
760	            validate_resource(target, object.resource.entry, object.facets);
761	            sync_file(target);
762	        }
763	        close_zip_reader(&input);
764	        fs::remove(changed_file);
765	    }
766	    for (const ObjectResource& object : capture.version.objects) {
767	        const fs::path path = fs::exists(pending / "new-resources" / (object.resource.id + ".zip")) ?
768	            pending / "new-resources" / (object.resource.id + ".zip") : resource_path(object.resource.id);
769	        require(fs::exists(path), "referenced object resource is missing");
770	    }
771	    checked_write(pending / "manifest.json", version_json(capture.version).dump(2));
772	    sync_file(pending / "metadata.3mf");
773	    sync_directory(pending);
774	    for (const ObjectResource& object : capture.version.objects) {
775	        const fs::path staged = pending / "new-resources" / (object.resource.id + ".zip");
776	        if (fs::exists(staged))
777	            atomic_replace(staged, resource_path(object.resource.id));
778	    }
779	    fs::remove_all(pending / "new-resources");
780	    fs::remove_all(pending / "writer-private");
781	    sync_directory(m_root / "resources");
782	    if (m_publish_stage_hook) m_publish_stage_hook(PublishStage::ResourcesDurable);
783	    sync_directory(pending);
784	    atomic_replace(pending, version_dir(capture.version.id));
785	    if (m_publish_stage_hook) m_publish_stage_hook(PublishStage::VersionPublished);
786	    auto committed = m_committed_ids;
787	    committed.push_back(capture.version.id);
788	    std::map<std::uint64_t, ObjectResource> next_resources;
789	    for (const ObjectResource& object : capture.version.objects)
790	        next_resources[object.object_id] = object;
791	    std::string next_head = capture.version.id;
792	    std::string next_digest = archive_digest(version_dir(capture.version.id) / "metadata.3mf");
793	    checked_write(m_root / "HEAD.pending",
794	                  json{{"schema", 1}, {"current", capture.version.id}, {"versions", committed}}.dump());
795	    replace_file(m_root / "HEAD.pending", m_root / "HEAD");
796	    m_committed_ids.swap(committed);
797	    m_head_id.swap(next_head);
798	    m_last_resources.swap(next_resources);
799	    m_last_signatures = std::move(capture.signatures);
800	    m_last_model = std::move(capture.frozen);
801	    m_last_metadata_digest.swap(next_digest);
802	    m_last_regions = capture.version.regions;
803	    m_head_needs_sync = true;
804	    ensure_durable_head();
805	    if (m_publish_stage_hook) m_publish_stage_hook(PublishStage::HeadPublished);
806	}
