808	void ProjectVersionStore::publish_document(std::string semantic_state)
809	{
810	    const json state = json::parse(semantic_state);
811	    require(state.is_object() && state.contains("project") && state["project"].is_object(),
812	            "project document has no identity");
813	    const std::string document_id = state["project"].value("projectId", std::string());
814	    require(document_id == m_project_id,
815	            "project document " + document_id + " does not match local project " + m_project_id);
816	    if (m_document_durable && semantic_state == m_last_semantic_state)
817	        return;
818	    create_on_first_write();
819	    validate_attachments(m_root, semantic_state);
820	    checked_write(m_root / "current-state.pending",
821	                  json{{"schema", 2}, {"state", state}}.dump());
822	    atomic_replace(m_root / "current-state.pending", m_root / "current-state.json");
823	    m_last_semantic_state = std::move(semantic_state);
824	    m_document_durable = true;
825	}
