852	ProjectVersionStore::Materialization ProjectVersionStore::materialize(const std::string& version_id) const
853	{
854	    const Version version = read_version(version_id);
855	    Materialization result;
856	    result.directory = m_root / "materialized" / new_id();
857	    result.metadata = result.directory / ".3mf";
858	    result.absent_original = result.directory / "source-unavailable.3mf";
859	    result.empty = version.objects.empty();
860	    result.regions = version.regions;
861	    fs::create_directories(result.directory / "3D" / "Objects");
862	    const fs::path stored_metadata = version_dir(version_id) / "metadata.3mf";
863	    validate_metadata(stored_metadata, version);
864	    fs::copy_file(stored_metadata, result.metadata);
865	    result.semantic_state = m_last_semantic_state;
866	    require(json::parse(result.semantic_state).is_object(), "current project document is invalid");
867	    validate_attachments(m_root, result.semantic_state);
868	    for (const ObjectResource& object : version.objects) {
869	        const fs::path source = resource_path(object.resource.id);
870	        validate_resource(source, object.resource.entry, object.facets);
871	        copy_or_relabel(source, object.resource.entry, result.directory / fs::u8path(object.entry), object.entry);
872	    }
873	    return result;
874	}
