904	    const fs::path file = directory / (action_id + ".json");
905	    require(!fs::exists(file), "operation version record already exists");
906	    const fs::path staged = directory / (action_id + ".pending");
907	    checked_write(staged, json{{"schema", 1}, {"actionId", action_id}, {"tool", tool},
908	                               {"outcome", outcome}, {"before", before}, {"after", after}}.dump(2));
909	    atomic_replace(staged, file);
910	}
