912	void ProjectVersionStore::prune(std::size_t max_versions, std::uintmax_t max_bytes,
913	                                const std::set<std::string>& live_attachments)
914	{
915	    require(max_versions >= 1 && max_bytes > 0, "invalid retention budget");
916	    std::set<std::string> protected_ids{m_head_id};
917	    if (fs::exists(m_root / "pins.json"))
918	        for (const json& item : json::parse(read_file(m_root / "pins.json")))
919	            protected_ids.insert(item.get<std::string>());
920	    for (const auto& entry : fs::directory_iterator(m_root / "operations")) {
921	        if (!entry.is_regular_file() || entry.path().extension() != ".json")
922	            continue;
923	        const json operation = json::parse(read_file(entry.path()));
924	        for (const char* field : {"before", "after"}) {
925	            const std::string id = operation.value(field, "");
926	            if (!id.empty()) protected_ids.insert(id);
927	        }
928	    }
929	    auto versions = history();
930	    const auto reachable_files = [this, &live_attachments](const std::vector<Version>& retained) {
931	        std::set<std::string> resources;
932	        std::set<std::string> attachments = live_attachments;
933	        if (!m_last_semantic_state.empty()) {
934	            const auto current_paths = attachment_paths(m_last_semantic_state);
935	            attachments.insert(current_paths.begin(), current_paths.end());
936	        }
937	        std::uintmax_t bytes = 0;
938	        for (const Version& version : retained) {
939	            for (const auto& entry : fs::recursive_directory_iterator(version_dir(version.id)))
940	                if (entry.is_regular_file()) bytes += entry.file_size();
941	            for (const ObjectResource& object : version.objects)
942	                resources.insert(object.resource.id);
943	        }
944	        for (const std::string& id : resources)
945	            bytes += fs::file_size(resource_path(id));
946	        for (const std::string& path : attachments)
947	            if (fs::exists(m_root / fs::u8path(path)))
948	                bytes += fs::file_size(m_root / fs::u8path(path));
949	        return std::make_tuple(bytes, resources, attachments);
950	    };
951	    std::set<std::string> removed;
952	    while (true) {
953	        const auto bytes = std::get<0>(reachable_files(versions));
954	        if (versions.size() <= max_versions && bytes <= max_bytes)
955	            break;
956	        const auto candidate = std::find_if(versions.begin(), versions.end(), [&protected_ids](const Version& version) {
957	            return !protected_ids.count(version.id);
958	        });
959	        if (candidate == versions.end())
960	            break; // The budget is soft when all remaining history is protected.
961	        removed.insert(candidate->id);
962	        versions.erase(candidate);
963	    }
964	    const auto [retained_bytes, kept_resources, kept_attachments] = reachable_files(versions);
965	    (void)retained_bytes;
966	    if (!removed.empty()) {
967	        std::vector<std::string> committed;
968	        for (const std::string& id : m_committed_ids)
969	            if (!removed.count(id)) committed.push_back(id);
970	        // Publish reachability before deleting files. A crash after this point
971	        // leaves only orphaned data, which recover_uncommitted() can remove.
972	        checked_write(m_root / "HEAD.pending",
973	                      json{{"schema", 1}, {"current", m_head_id}, {"versions", committed}}.dump());
974	        atomic_replace(m_root / "HEAD.pending", m_root / "HEAD");
975	        m_committed_ids.swap(committed);
976	        for (const std::string& id : removed)
977	            fs::remove_all(version_dir(id));
978	        sync_directory(m_root / "versions");
979	    }
980	    for (const auto& resource : fs::directory_iterator(m_root / "resources"))
981	        if (resource.is_regular_file() && !kept_resources.count(resource.path().stem().string()))
982	            fs::remove(resource.path());
983	    sync_directory(m_root / "resources");
984	    if (fs::exists(m_root / "attachments")) {
985	        for (const auto& entry : fs::recursive_directory_iterator(m_root / "attachments"))
986	            if (entry.is_regular_file() &&
987	                !kept_attachments.count(fs::relative(entry.path(), m_root).generic_u8string()))
988	                fs::remove(entry.path());
989	        sync_directory(m_root / "attachments");
990	    }
991	}
992

280	    }
281	}
