319	void ProjectAutosave::observe_document_change()
320	{
321	    const auto revision = m_persistence.document().doc_revision();
322	    if (revision == m_seen_semantic_revision)
323	        return;
324	    const auto now = Clock::now();
325	    m_seen_semantic_revision = revision;
326	    m_last_semantic_edit = now;
327	    if (!m_first_semantic_edit)
328	        m_first_semantic_edit = now;
329	    m_state = State::Saving;
