332	std::string ProjectAutosave::observed_input() const
333	{
334	    // Only native printable project state belongs in checkpoint detection.
335	    // Conversation, plans, intent, audit, and print facts are durable in the
336	    // current document and cannot force a model export.
337	    // The scan touches identities, timestamps and small metadata, never mesh
338	    // triangles or Orca's 3MF writer.
339	    std::ostringstream out;
340	    out << std::setprecision(17) << m_event_sequence << ';';
341	    append_text(out, m_persistence.document().project_id());
342	    append_text(out, m_plater.get_project_name().ToUTF8().data());
343	    append_text(out, m_plater.get_project_filename(".3mf").ToUTF8().data());
344	    const Model& model = m_plater.model();
345	    out << model.id().id << ';' << model.objects.size() << ';';
346	    if (model.model_info) {
347	        append_text(out, model.model_info->cover_file);
348	        append_text(out, model.model_info->description);
349	        append_text(out, model.model_info->model_name);
350	    }
351	    for (const auto& [plate_index, codes] : model.plates_custom_gcodes) {
352	        out << plate_index << ',' << int(codes.mode) << ',' << codes.gcodes.size() << ';';
353	        for (const auto& code : codes.gcodes) {
354	            out << code.print_z << ',' << int(code.type) << ',' << code.extruder << ';';
355	            append_text(out, code.color);
356	            append_text(out, code.extra);
357	        }
358	    }
359	    for (const ModelObject* object : model.objects) {
360	        out << object->id().id << ',' << object->printable << ','
361	            << static_cast<const ModelConfig&>(object->config).timestamp()
362	            << ',' << object->layer_height_profile.timestamp() << ';';
363	        append_text(out, object->name);
364	        out << object->brim_points.size() << ';';
365	        for (const auto& point : object->brim_points)
366	            out << point.pos.x() << ',' << point.pos.y() << ',' << point.pos.z() << ',' << point.head_front_radius << ';';
367	        out << object->volumes.size() << ';';
368	        for (const ModelVolume* volume : object->volumes) {
369	            out << volume->id().id << ',' << volume->mesh_ptr().get() << ',' << int(volume->type())
370	                << ',' << static_cast<const ModelConfig&>(volume->config).timestamp()
371	                << ',' << volume->supported_facets.timestamp()
372	                << ',' << volume->seam_facets.timestamp() << ',' << volume->mmu_segmentation_facets.timestamp()
373	                << ',' << volume->fuzzy_skin_facets.timestamp() << ';';
374	            append_text(out, volume->name);
375	            append_text(out, volume->material_id());
376	            append_transform(out, volume->get_matrix());
377	        }
378	        out << object->instances.size() << ';';
379	        for (const ModelInstance* instance : object->instances) {
380	            out << instance->id().id << ',' << instance->printable << ',' << instance->auto_drop
381	                << ',' << instance->arrange_order << ';';
382	            append_transform(out, instance->get_matrix());
383	        }
384	    }
385	    PartPlateList& plates = m_plater.get_partplate_list();
386	    out << plates.get_plate_count() << ';';
387	    for (int index = 0; index < plates.get_plate_count(); ++index) {
388	        PartPlate* plate = plates.get_plate(index);
389	        out << plate->id().id << ',' << int(plate->get_bed_type()) << ',' << plate->is_locked()
390	            << ',' << int(plate->get_filament_map_mode()) << ';';
391	        append_text(out, plate->get_plate_name());
392	        for (int filament : plate->get_filament_maps()) out << filament << ',';
393	        out << ';';
394	        append_config(out, *plate->config());
395	    }
396	    if (const PresetBundle* presets = wxGetApp().preset_bundle)
397	        append_config(out, presets->full_config_secure());
398	    return out.str();
399	}
