401	void ProjectAutosave::trim_history()
402	{
403	    try {
404	        std::set<std::string> live_attachments;
405	        for (const auto& attachment : m_persistence.document().attachments())
406	            if (!attachment.stored_name.empty())
407	                live_attachments.insert(attachment.relative_path());
408	        m_store->prune(kMaxVersions, kMaxBytes, live_attachments);
409	        m_warning.clear();
410	    } catch (const std::exception& error) {
411	        // The current head was already committed. A retention failure leaves
412	        // extra old data and must not misreport the current project as unsaved.
413	        m_warning = std::string("Local history cleanup failed: ") + error.what();
414	        BOOST_LOG_TRIVIAL(warning) << m_warning;
415	    }
416	}
