418	bool ProjectAutosave::settle(bool wait)
419	{
420	    if (!m_worker.valid())
421	        return true;
422	    if (!wait && m_worker.wait_for(std::chrono::seconds(0)) != std::future_status::ready)
423	        return false;
424	    try {
425	        m_worker.get();
426	        if (m_worker_kind == WorkerKind::Model) {
427	            m_committed_head = m_store->head_id();
428	            m_last_capture_input = std::move(m_inflight_capture_input);
429	            m_seen_model_input = m_last_capture_input;
430	            trim_history();
431	        }
432	        if (m_worker_kind == WorkerKind::Document)
433	            m_committed_semantic_revision = m_inflight_semantic_revision;
434	        m_worker_kind = WorkerKind::None;
435	        if (m_seen_semantic_revision == m_committed_semantic_revision)
436	            m_first_semantic_edit.reset();
437	        m_error.clear();
438	        // A main-thread edit may have landed while the worker wrote the
439	        // frozen revision. Probe again before saying the current model is saved.
440	        m_state = State::Saving;
441	        m_next_probe = Clock::now();
442	        return true;
443	    } catch (const std::exception& error) {
444	        m_worker_kind = WorkerKind::None;
445	        m_inflight_capture_input.clear();
446	        fail(error.what());
447	    } catch (...) {
448	        m_worker_kind = WorkerKind::None;
449	        m_inflight_capture_input.clear();
450	        fail("project version writer failed");
451	    }
452	    return false;
453	}
