455	void ProjectAutosave::adopt_project()
456	{
457	    m_persistence.resolve_pending_boundary();
458	    const std::string id = m_persistence.document().project_id();
459	    if (m_store && m_store->project_id() == id)
460	        return;
461	    settle(true);
462	    m_store.reset();
463	    if (id.empty())
464	        throw std::runtime_error("open project has no identity");
465	    m_store = std::make_unique<ProjectVersionStore>(m_root, id);
466	    m_last_capture_input.clear();
467	    m_seen_model_input.clear();
468	    m_inflight_capture_input.clear();
469	    m_committed_head = m_store->head_id();
470	    m_committed_semantic_revision = m_committed_head.empty() ? 0 : m_persistence.document().doc_revision();
471	    m_seen_semantic_revision = m_persistence.document().doc_revision();
472	    m_last_semantic_edit = Clock::now();
473	    m_first_semantic_edit = m_seen_semantic_revision != m_committed_semantic_revision ?
474	        std::optional<Clock::time_point>(m_last_semantic_edit) : std::nullopt;
475	    const auto versions = m_store->history();
476	    m_project_name = versions.empty() ? std::string() : versions.back().project_name;
477	    m_opened_from = versions.empty() ? std::string() : versions.back().opened_from;
478	    m_opened_digest = versions.empty() ? std::string() : versions.back().opened_digest;
479	    if (const std::string file = m_plater.get_project_filename(".3mf").ToUTF8().data(); versions.empty() && !file.empty()) {
480	        m_opened_from = file;
481	        m_opened_digest = file_digest(std::filesystem::u8path(file));
482	    }
483	    m_revision = 0;
484	    for (const auto& version : versions)
485	        m_revision = std::max(m_revision, version.revision);
486	    m_state = State::Saving;
487	    m_next_probe = Clock::now();
488	}
