490	bool ProjectAutosave::capture(bool wait_for_commit)
491	{
492	    if (!m_store)
493	        return false;
494	    std::filesystem::path metadata;
495	    try {
496	        const std::string id = ProjectVersionStore::new_id();
497	        metadata = m_store->pending_metadata_path(id);
498	        ++m_capture_attempts;
499	        const int result = m_plater.export_3mf(boost_path(metadata),
500	                                                SaveStrategy::Backup | SaveStrategy::Silence);
501	        if (result < 0)
502	            throw std::runtime_error("OrcaSlicer could not capture project metadata");
503	        protect_saved_settings(metadata);
504	        const wxString source = m_plater.get_project_filename(".3mf");
505	        auto frozen = m_store->freeze(m_plater.model(), id, ++m_revision, m_persistence.document().dump(),
506	                                      source.ToUTF8().data(), m_persistence.timestamp());
507	        const auto& changes = m_persistence.document().changes();
508	        if (!changes.empty())
509	            frozen.version.change_seq = changes.back().seq;
510	        const auto semantic_revision = m_persistence.document().doc_revision();
511	        m_committed_semantic_revision = semantic_revision;
512	        if (m_seen_semantic_revision == semantic_revision)
513	            m_first_semantic_edit.reset();
514	        const std::string plater_name(m_plater.get_project_name().ToUTF8());
515	        frozen.version.project_name = m_project_name.empty() ? plater_name : m_project_name;
516	        if ((plater_name.empty() || plater_name == _L("Untitled").ToUTF8().data()) &&
517	            !m_plater.model().objects.empty())
518	            frozen.version.project_name = std::filesystem::u8path(m_plater.model().objects.front()->name).stem().u8string();
519	        m_project_name = frozen.version.project_name;
520	        // A project adopted before Orca named its file gets it with its first
521	        // version.
522	        if (m_opened_from.empty() && m_store->head_id().empty() && !source.empty()) {
523	            m_opened_from   = source.ToUTF8().data();
524	            m_opened_digest = file_digest(std::filesystem::u8path(m_opened_from));
525	        }
526	        frozen.version.opened_from = m_opened_from;
527	        frozen.version.opened_digest = m_opened_digest;
528	        if (m_store->unchanged(frozen)) {
529	            m_store->discard(frozen);
530	            m_last_capture_input = observed_input();
531	            m_seen_model_input = m_last_capture_input;
532	            m_seen_semantic_revision = semantic_revision;
533	            m_first_semantic_edit.reset();
534	            m_error.clear();
535	            m_state = State::Saved;
536	            return true;
537	        }
538	        m_state = State::Saving;
539	        if (wait_for_commit) {
540	            m_store->publish(std::move(frozen));
541	            m_committed_head = m_store->head_id();
542	            m_last_capture_input = observed_input();
543	            m_seen_model_input = m_last_capture_input;
544	            m_seen_semantic_revision = semantic_revision;
545	            m_first_semantic_edit.reset();
546	            trim_history();
547	            m_error.clear();
548	            m_state = State::Saved;
549	        } else {
550	            m_inflight_capture_input = observed_input();
551	            m_seen_model_input = m_inflight_capture_input;
552	            m_inflight_semantic_revision = semantic_revision;
553	            m_worker_kind = WorkerKind::Model;
554	            m_worker = std::async(std::launch::async, [this, frozen = std::move(frozen)]() mutable {
555	                m_store->publish(std::move(frozen));
556	            });
557	        }
558	        return true;
559	    } catch (const std::exception& error) {
560	        m_worker_kind = WorkerKind::None;
561	        if (!metadata.empty())
562	            std::filesystem::remove_all(metadata.parent_path());
563	        fail(error.what());
564	    }
565	    return false;
566	}
