568	bool ProjectAutosave::persist_document(bool wait_for_commit)
569	{
570	    if (!m_store)
571	        return false;
572	    try {
573	        const std::string state = m_persistence.document().dump();
574	        const auto revision = m_persistence.document().doc_revision();
575	        m_state = State::Saving;
576	        if (wait_for_commit) {
577	            m_store->publish_document(state);
578	            m_committed_semantic_revision = revision;
579	            m_seen_semantic_revision = revision;
580	            m_first_semantic_edit.reset();
581	            m_error.clear();
582	            m_state = State::Saved;
583	        } else {
584	            m_inflight_semantic_revision = revision;
585	            m_worker_kind = WorkerKind::Document;
586	            m_worker = std::async(std::launch::async, [this, state] {
587	                m_store->publish_document(state);
588	            });
589	        }
590	        return true;
591	    } catch (const std::exception& error) {
592	        m_worker_kind = WorkerKind::None;
593	        fail(error.what());
594	        return false;
595	    }
596	}
