598	void ProjectAutosave::tick()
599	{
600	    try {
601	        if (!m_resume_attempted) {
602	            GLCanvas3D* canvas = m_plater.get_view3D_canvas3D();
603	            if (canvas == nullptr || !canvas->is_initialized())
604	                return;
605	            resume_latest();
606	        }
607	        adopt_project();
608	        if (!settle(false) && m_worker.valid())
609	            return;
610	        observe_document_change();
611	        const auto now = Clock::now();
612	        if (now < m_next_probe)
613	            return;
614	        m_next_probe = now + kProbeInterval;
615	        if (m_plater.model().objects.empty() && m_store->head_id().empty() &&
616	            m_persistence.document().doc_revision() <= 1) {
617	            m_state = State::Saved;
618	            return;
619	        }
620	        const std::string model_input = observed_input();
621	        if (model_input != m_seen_model_input) {
622	            m_seen_model_input = model_input;
623	            m_last_edit = now;
624	            m_state = State::Saving;
625	        }
626	        const bool document_pending = m_persistence.document().doc_revision() != m_committed_semantic_revision;
627	        const bool document_due = document_pending &&
628	            (now - m_last_semantic_edit >= kEditQuietPeriod ||
629	             (m_first_semantic_edit && now - *m_first_semantic_edit >= kSemanticMaxDelay));
630	        // A continuously edited model must not starve the current document.
631	        // Model capture also publishes the document, so a ready model still
632	        // takes precedence until the document's maximum delay is reached.
633	        if (document_due && m_first_semantic_edit && now - *m_first_semantic_edit >= kSemanticMaxDelay) {
634	            persist_document(false);
635	            return;
636	        }
637	        const bool model_pending = m_store->head_id().empty() || model_input != m_last_capture_input;
638	        const bool held          = model_pending && m_capture_hold && m_capture_hold();
639	        if (model_pending && !held) {
640	            GLCanvas3D* canvas = m_plater.get_view3D_canvas3D();
641	            if (canvas == nullptr || !canvas->is_initialized() ||
642	                canvas->get_gizmos_manager().is_in_editing_mode(true) ||
643	                now - m_last_edit < kEditQuietPeriod)
644	                return;
645	            capture(false);
646	        } else if (document_pending) {
647	            if (!document_due)
648	                return;
649	            persist_document(false);
650	        } else if (!held) {
651	            m_state = State::Saved;
652	            m_first_semantic_edit.reset();
653	        }
654	    } catch (const std::exception& error) {
655	        fail(error.what());
656	    }
657	}
