51	std::string saved_preview(const std::filesystem::path& project, const std::string& version)
52	{
53	    std::ifstream file(preview_path(project), std::ios::binary);
54	    if (!file) return {};
55	    const auto saved = nlohmann::json::parse(file, nullptr, false);
56	    if (!saved.is_object() || !saved.contains("version") || !saved["version"].is_string() ||
57	        !saved.contains("url") || !saved["url"].is_string() || saved["version"] != version)
58	        return {};
59	    const std::string url = saved["url"].get<std::string>();
60	    return url.size() <= (kMaxPreviewBytes * 4 / 3 + 64) &&
61	           url.rfind("data:image/png;base64,", 0) == 0 ? url : std::string();
62	}
