64	void write_preview(const std::filesystem::path& project, const std::string& version, const std::string& url)
65	{
66	    const auto temporary = project / ("preview-" + ProjectVersionStore::new_id() + ".tmp");
67	    {
68	        std::ofstream file(temporary, std::ios::binary | std::ios::trunc);
69	        file << nlohmann::json{{"version", version}, {"url", url}}.dump();
70	        file.flush();
71	        if (!file) throw std::runtime_error("Could not write local project preview");
72	    }
73	    std::error_code error;
74	#ifdef _WIN32
75	    std::filesystem::remove(preview_path(project), error);
76	    error.clear();
77	#endif
78	    std::filesystem::rename(temporary, preview_path(project), error);
79	    if (error) {
80	        std::filesystem::remove(temporary);
81	        throw std::runtime_error("Could not publish local project preview: " + error.message());
82	    }
83	}
