138	bool authored_head(const std::filesystem::path& project)
139	{
140	    std::ifstream head(project / "HEAD", std::ios::binary);
141	    std::string content((std::istreambuf_iterator<char>(head)), std::istreambuf_iterator<char>());
142	    if (content.empty()) return false;
143	    const std::string id = nlohmann::json::parse(content).at("current").get<std::string>();
144	    const auto version = project / "versions" / id;
145	    std::ifstream manifest_file(version / "manifest.json", std::ios::binary);
146	    const auto manifest = nlohmann::json::parse(manifest_file);
147	    if (!manifest.at("objects").empty())
148	        return true;
149	    const auto current_path = project / "current-state.json";
150	    if (!std::filesystem::exists(current_path))
151	        return false;
152	    std::ifstream current_file(current_path, std::ios::binary);
153	    return nlohmann::json::parse(current_file).at("state").value("docRevision", std::uint64_t{0}) > 1;
154	}
