156	// The MD5 of a file's content; empty when it cannot be read.
157	std::string file_digest(const std::filesystem::path& path)
158	{
159	    try {
160	        std::string name = path.u8string(), digest;
161	        return std::filesystem::is_regular_file(path) && bbl_calc_md5(name, digest) ? digest : std::string();
162	    } catch (const std::exception&) {
163	        return {};
164	    }
165	}
