167	bool same_source_path(const std::filesystem::path& first, const std::filesystem::path& second)
168	{
169	    if (first.empty() || second.empty()) return false;
170	    std::error_code error;
171	    if (std::filesystem::exists(first, error) && !error &&
172	        std::filesystem::exists(second, error) && !error &&
173	        std::filesystem::equivalent(first, second, error) && !error)
174	        return true;
175	    error.clear();
176	    const auto normalized_first = std::filesystem::weakly_canonical(first, error);
177	    if (error) return false;
178	    error.clear();
179	    const auto normalized_second = std::filesystem::weakly_canonical(second, error);
180	    if (error) return false;
181	#ifdef _WIN32
182	    std::wstring left = normalized_first.wstring(), right = normalized_second.wstring();
183	    std::transform(left.begin(), left.end(), left.begin(), [](wchar_t value) { return std::towlower(value); });
184	    std::transform(right.begin(), right.end(), right.begin(), [](wchar_t value) { return std::towlower(value); });
185	    return left == right;
186	#else
187	    return normalized_first == normalized_second;
188	#endif
189	}
