213	// Managed checkpoints keep their captured settings; ordinary 3MF exports keep Orca's
214	// actual preset-difference list. Rewrite only the unpublished backup archive.
215	void protect_saved_settings(const std::filesystem::path& metadata)
216	{
217	    constexpr const char* entry = "Metadata/project_settings.config";
218	    mz_zip_archive source, target;
219	    mz_zip_zero_struct(&source);
220	    mz_zip_zero_struct(&target);
221	    if (!open_zip_reader(&source, metadata.u8string()))
222	        throw std::runtime_error("Could not read captured project metadata");
223	
224	    bool target_open = false;
225	    auto rewritten = metadata;
226	    rewritten += ".rewrite";
227	    try {
228	        const int entry_index = mz_zip_reader_locate_file(&source, entry, nullptr, 0);
229	        if (entry_index < 0)
230	            throw std::runtime_error("Captured project settings are missing");
231	        size_t size = 0;
232	        void* data = mz_zip_reader_extract_file_to_heap(&source, entry, &size, 0);
233	        if (!data)
234	            throw std::runtime_error("Could not read captured project settings");
235	        std::string original(static_cast<const char*>(data), size);
236	        mz_free(data);
237	
238	        auto settings = nlohmann::json::parse(original);
239	        const auto& colours = settings.at("filament_colour");
240	        if (!colours.is_array() || colours.empty())
241	            throw std::runtime_error("Captured project has no filament settings");
242	        std::vector<std::string> keys;
243	        for (auto it = settings.begin(); it != settings.end(); ++it)
244	            if (it.key() != "version" && it.key() != "name" && it.key() != "from" &&
245	                it.key() != "different_settings_to_system")
246	                keys.push_back(it.key());
247	        const std::string protected_keys = escape_strings_cstyle(keys);
248	        settings["different_settings_to_system"] =
249	            std::vector<std::string>(colours.size() + 2, protected_keys);
250	        const std::string replacement = settings.dump(1, '\t') + '\n';
251	
252	        if (!open_zip_writer(&target, rewritten.u8string()))
253	            throw std::runtime_error("Could not rewrite captured project metadata");
254	        target_open = true;
255	        for (mz_uint index = 0; index < mz_zip_reader_get_num_files(&source); ++index) {
256	            const bool added = int(index) == entry_index ?
257	                mz_zip_writer_add_mem(&target, entry, replacement.data(), replacement.size(), MZ_DEFAULT_COMPRESSION) :
258	                mz_zip_writer_add_from_zip_reader(&target, &source, index);
259	            if (!added)
260	                throw std::runtime_error("Could not copy captured project metadata entry");
261	        }
262	        if (!mz_zip_writer_finalize_archive(&target))
263	            throw std::runtime_error("Could not finalize captured project metadata");
264	        target_open = false;
265	        if (!close_zip_writer(&target))
266	            throw std::runtime_error("Could not close rewritten project metadata");
267	        if (!close_zip_reader(&source))
268	            throw std::runtime_error("Could not close captured project metadata");
269	#ifdef _WIN32
270	        // This archive is still unpublished staging data; Windows cannot rename over it.
271	        std::filesystem::remove(metadata);
272	#endif
273	        std::filesystem::rename(rewritten, metadata);
274	    } catch (...) {
275	        if (target_open) close_zip_writer(&target);
276	        if (source.m_zip_mode == MZ_ZIP_MODE_READING) close_zip_reader(&source);
277	        std::error_code ignored;
278	        std::filesystem::remove(rewritten, ignored);
279	        throw;
280	    }

699	        if (head.empty())
700	            throw std::runtime_error("recent managed project has no current version");
701	        const auto materialized = opened->materialize(head);
702	        const auto versions = opened->history();
703	        const auto selected = std::find_if(versions.begin(), versions.end(), [&head](const auto& item) {
704	            return item.id == head;
705	        });
706	        if (selected == versions.end())
707	            throw std::runtime_error("recent managed project has no current manifest");
708	        m_plater.reset();
709	        m_plater.take_snapshot("Resume local project", UndoRedo::SnapshotType::ProjectSeparator);
710	        auto strategy = LoadStrategy::Restore;
711	        if (materialized.empty)
712	            strategy = strategy | LoadStrategy::AllowEmpty;
713	        const auto loaded = load_managed_checkpoint(m_plater, materialized, strategy);
714	        if ((loaded.empty() && !materialized.empty) || (materialized.empty && !m_plater.model().objects.empty()))
715	            throw std::runtime_error("recent managed project could not be restored");
716	        m_plater.set_project_filename(wxString::FromUTF8(selected->source_path));
717	        m_project_name = selected->project_name;
718	        m_opened_from = selected->opened_from;
719	        m_opened_digest = selected->opened_digest;
720	        m_persistence.adopt_managed_state(materialized.semantic_state);
721	        opened->seed_from_live(m_plater.model());
722	        m_last_capture_input = observed_input();
723	        m_seen_model_input = m_last_capture_input;
724	        m_committed_semantic_revision = m_persistence.document().doc_revision();
725	        m_seen_semantic_revision = m_committed_semantic_revision;
726	        m_first_semantic_edit.reset();
727	        m_revision = 0;
728	        for (const auto& version : versions)
729	            m_revision = std::max(m_revision, version.revision);
730	        m_committed_head = head;
731	        m_store = std::move(opened);
732	        m_active_materialization = materialized;
733	        m_active_materialization_project = m_store->project_id();
734	        m_error.clear();
735	        m_state = State::Saved;
736	        m_next_probe = Clock::now() + kProbeInterval;
737	        return true;
738	    } catch (const std::exception& error) {
739	        fail(error.what());
740	        return false;
741	    }
742	}
