744	std::vector<ProjectAutosave::ManagedProject> ProjectAutosave::projects()
745	{
746	    settle(true);
747	    // Home can be opened before the first project switch. Render the current
748	    // project once here; the preview is independent of the frequent backups.
749	    ensure_current_preview();
750	    std::vector<ManagedProject> result;
751	    // Nothing has been saved yet on a new installation.
752	    if (!std::filesystem::is_directory(m_root))
753	        return result;
754	    for (const auto& entry : std::filesystem::directory_iterator(m_root)) {
755	        if (!entry.is_directory() || !std::filesystem::exists(entry.path() / "HEAD"))
756	            continue;
757	        try {
758	            if (!authored_head(entry.path()))
759	                continue;
760	            const std::string id = entry.path().filename().string();
761	            const auto add = [&result, &entry, &id](const ProjectVersionStore::Version& version) {
762	                const auto source = std::filesystem::u8path(version.source_path);
763	                const std::string name = !version.project_name.empty() ? version.project_name : source.stem().u8string();
764	                ManagedProject project{id, name, version.created_at, version.source_path, entry.path().u8string()};
765	                try {
766	                    project.thumbnail_url = saved_preview(entry.path(), version.id);
767	                    if (project.thumbnail_url.empty()) {
768	                        // A project whose latest version was never rendered
769	                        // here has no preview sidecar for it. Orca's original
770	                        // 3MF thumbnail keeps its Home card useful until the
771	                        // project is next opened and rendered locally.
772	                        project.thumbnail_url = source_preview(version.source_path);
773	                        if (!project.thumbnail_url.empty())
774	                            write_preview(entry.path(), version.id, project.thumbnail_url);
775	                    }
776	                } catch (const std::exception& error) {
777	                    // A damaged preview must not hide an otherwise healthy
778	                    // local project from Home.
779	                    BOOST_LOG_TRIVIAL(warning) << "Local project preview unavailable: " << error.what();
780	                }
781	                result.push_back(std::move(project));
782	            };
783	            if (m_store && id == m_store->project_id()) {
784	                const auto versions = m_store->history();
785	                if (!versions.empty())
786	                    add(versions.back());
787	            } else {
788	                ProjectVersionStore other(m_root, id);
789	                const auto versions = other.history();
790	                if (!versions.empty())
791	                    add(versions.back());
792	            }
793	        } catch (const std::exception& error) {
794	            BOOST_LOG_TRIVIAL(warning) << "Managed project unavailable: " << entry.path().string() << ": " << error.what();
795	        }
796	    }
797	    std::sort(result.begin(), result.end(), [](const ManagedProject& a, const ManagedProject& b) {
798	        return a.updated_at > b.updated_at;
799	    });
800	    return result;
801	}
