808	std::vector<ProjectAutosave::SourceMatch> ProjectAutosave::projects_for_source(const std::filesystem::path& source) const
809	{
810	    if (source.empty())
811	        return {};
812	    std::optional<std::string> digest_now; // read once, when a match needs it
813	    const auto changed = [&](const std::string& digest) -> std::optional<bool> {
814	        if (digest.empty())
815	            return std::nullopt;
816	        if (!digest_now)
817	            digest_now = file_digest(source);
818	        return *digest_now != digest;
819	    };
820	    std::vector<std::pair<std::filesystem::file_time_type, SourceMatch>> matches;
821	    if (!std::filesystem::is_directory(m_root))
822	        return {};
823	    for (const auto& entry : std::filesystem::directory_iterator(m_root)) {
824	        if (!entry.is_directory() || !std::filesystem::is_regular_file(entry.path() / "HEAD"))
825	            continue;
826	        try {
827	            std::ifstream head_file(entry.path() / "HEAD", std::ios::binary);
828	            const std::string head((std::istreambuf_iterator<char>(head_file)), std::istreambuf_iterator<char>());
829	            if (head.empty()) continue;
830	            std::vector<std::string> versions;
831	            if (head.front() == '{')
832	                versions = nlohmann::json::parse(head).at("versions").get<std::vector<std::string>>();
833	            else {
834	                std::string version = head;
835	                if (!version.empty() && version.back() == '\n') version.pop_back();
836	                versions.push_back(std::move(version));
837	            }
838	            for (auto it = versions.rbegin(); it != versions.rend(); ++it) {
839	                if (it->empty() || it->find_first_of("/\\") != std::string::npos) continue;
840	                std::ifstream manifest_file(entry.path() / "versions" / *it / "manifest.json", std::ios::binary);
841	                if (!manifest_file) continue;
842	                const nlohmann::json manifest = nlohmann::json::parse(manifest_file);
843	                if (same_source_path(source, std::filesystem::u8path(manifest.value("sourcePath", std::string()))) ||
844	                    same_source_path(source, std::filesystem::u8path(manifest.value("openedFrom", std::string())))) {
845	                    auto updated = std::filesystem::last_write_time(entry.path() / "HEAD");
846	                    if (std::filesystem::is_regular_file(entry.path() / "current-state.json"))
847	                        updated = std::max(updated, std::filesystem::last_write_time(entry.path() / "current-state.json"));
848	                    matches.emplace_back(updated, SourceMatch{entry.path().filename().string(), manifest.value("projectName", std::string()),
849	                                                              false, changed(manifest.value("openedDigest", std::string()))});
850	                    break;
851	                }
852	            }
853	        } catch (const std::exception& error) {
854	            BOOST_LOG_TRIVIAL(warning) << "Local project source index unavailable: " << entry.path().string()
855	                                       << ": " << error.what();
856	        }
857	    }
858	    std::sort(matches.begin(), matches.end(), [](const auto& a, const auto& b) {
859	        return a.first != b.first ? a.first > b.first : a.second.id > b.second.id;
860	    });
861	    std::vector<SourceMatch> result;
862	    result.reserve(matches.size());
863	    for (const auto& [updated, match] : matches)
864	        result.push_back(match);
865	    const wxString     current_source = m_plater.get_project_filename(".3mf");
866	    const std::string& current_id     = m_persistence.document().project_id();
867	    const bool         ours           = m_store && m_store->project_id() == current_id;
868	    if (same_source_path(source, std::filesystem::u8path(current_source.ToUTF8().data())) ||
869	        (ours && same_source_path(source, std::filesystem::u8path(m_opened_from)))) {
870	        auto current = std::find_if(result.begin(), result.end(), [&](const SourceMatch& match) { return match.id == current_id; });
871	        if (current != result.end())
872	            std::rotate(result.begin(), current, current + 1);
873	        else if (!current_id.empty())
874	            result.insert(result.begin(), SourceMatch{current_id, project_name()});
875	        result.front().current = true;
876	        if (ours)
877	            result.front().changed = changed(m_opened_digest);
878	    }
879	    return result;
880	}
