891	bool ProjectAutosave::open_managed_project(const std::string& project_id)
892	{
893	    if (!save_now())
894	        return false;
895	    ensure_current_preview();
896	    if (m_store->project_id() == project_id)
897	        return true;
898	    const std::string previous_id = m_store->head_id();
899	    std::optional<ProjectVersionStore::Materialization> target_materialized;
900	    std::unique_ptr<ProjectVersionStore> target;
901	    bool replacement_started = false;
902	    const auto load = [this](const ProjectVersionStore::Materialization& materialized,
903	                             const ProjectVersionStore::Version& version) {
904	        m_plater.reset();
905	        m_plater.take_snapshot("Open local project", UndoRedo::SnapshotType::ProjectSeparator);
906	        auto strategy = LoadStrategy::Restore;
907	        if (materialized.empty)
908	            strategy = strategy | LoadStrategy::AllowEmpty;
909	        const auto loaded = load_managed_checkpoint(m_plater, materialized, strategy);
910	        if ((loaded.empty() && !materialized.empty) || (materialized.empty && !m_plater.model().objects.empty()))
911	            throw std::runtime_error("local project could not be restored");
912	        m_plater.set_project_filename(wxString::FromUTF8(version.source_path));
913	    };
914	    try {
915	        target = std::make_unique<ProjectVersionStore>(m_root, project_id);
916	        const auto versions = target->history();
917	        if (versions.empty() || versions.back().id != target->head_id())
918	            throw std::runtime_error("local project has no current version");
919	        target_materialized = target->materialize(target->head_id());
920	        replacement_started = true;
921	        load(*target_materialized, versions.back());
922	        m_persistence.adopt_managed_state(target_materialized->semantic_state);
923	        target->seed_from_live(m_plater.model());
924	        m_last_capture_input = observed_input();
925	        m_seen_model_input = m_last_capture_input;
926	        m_committed_semantic_revision = m_persistence.document().doc_revision();
927	        m_seen_semantic_revision = m_committed_semantic_revision;
928	        m_first_semantic_edit.reset();
929	        if (m_active_materialization && m_active_materialization_project == m_store->project_id()) {
930	            try {
931	                m_store->remove_materialization(*m_active_materialization);
932	            } catch (const std::exception& cleanup_error) {
933	                m_warning = std::string("Old project workspace could not be removed: ") + cleanup_error.what();
934	                BOOST_LOG_TRIVIAL(warning) << m_warning;
935	            }
936	        }
937	        m_store = std::move(target);
938	        m_project_name = versions.back().project_name;
939	        m_opened_from = versions.back().opened_from;
940	        m_opened_digest = versions.back().opened_digest;
941	        m_active_materialization = *target_materialized;
942	        m_active_materialization_project = project_id;
943	        m_committed_head = m_store->head_id();
944	        m_revision = 0;
945	        for (const auto& version : versions)
946	            m_revision = std::max(m_revision, version.revision);
947	        m_error.clear();
948	        m_state = State::Saved;
949	        m_resume_attempted = true;
950	        m_next_probe = Clock::now() + kProbeInterval;
951	        return true;
952	    } catch (const std::exception& error) {
953	        const std::string reason = error.what();
954	        if (replacement_started) {
955	            try {
956	                const auto previous = m_store->materialize(previous_id);
957	                const auto versions = m_store->history();
958	                const auto old = std::find_if(versions.begin(), versions.end(), [&previous_id](const auto& version) {
959	                    return version.id == previous_id;
960	                });
961	                if (old == versions.end())
962	                    throw std::runtime_error("previous project version was not found");
963	                load(previous, *old);
964	                m_persistence.adopt_managed_state(previous.semantic_state);
965	                m_store->seed_from_live(m_plater.model());
966	                m_active_materialization = previous;
967	                m_active_materialization_project = m_store->project_id();
968	                if (target && target_materialized)
969	                    target->remove_materialization(*target_materialized);
970	            } catch (const std::exception& rollback_error) {
971	                fail(reason + "; previous project also failed to reload: " + rollback_error.what());
972	                return false;
973	            }
974	        }
975	        fail(reason);
976	        return false;
977	    }
978	}
