980	void ProjectAutosave::ensure_current_preview()
981	{
982	    if (!m_store || m_store->head_id().empty() || m_plater.model().objects.empty())
983	        return;
984	    try {
985	        const auto project = m_root / m_store->project_id();
986	        if (!saved_preview(project, m_store->head_id()).empty())
987	            return;
988	        GLCanvas3D* canvas = m_plater.get_view3D_canvas3D();
989	        if (canvas == nullptr || !canvas->is_initialized() || m_plater.get_partplate_list().get_plate_count() == 0)
990	            return;
991	        ThumbnailData data;
992	        // Frame all model volumes, including objects on other plates.
993	        ThumbnailsParams params{{}, false, true, false, true, 0, false};
994	        canvas->render_thumbnail(data, 256, 256, params, Camera::EType::Ortho);
995	        if (!data.is_valid())
996	            return;
997	        const bool has_subject = [&data] {
998	            for (std::size_t pixel = 3; pixel < data.pixels.size(); pixel += 4)
999	                if (data.pixels[pixel] != 0)
1000	                    return true;
1001	            return false;
1002	        }();
1003	        if (!has_subject)
1004	            return;
1005	        const auto png = GCodeThumbnails::compress_thumbnail(data, GCodeThumbnailsFormat::PNG);
1006	        if (!png || !png->data || png->size == 0 || png->size > kMaxPreviewBytes)
1007	            return;
1008	        write_preview(project, m_store->head_id(),
1009	                      "data:image/png;base64," + base64_encode(std::string(static_cast<const char*>(png->data), png->size)));
1010	    } catch (const std::exception& error) {
1011	        // A preview is derived display data. A failed render or cache write
1012	        // must not prevent opening the committed project.
1013	        BOOST_LOG_TRIVIAL(warning) << "Local project preview unavailable: " << error.what();
1014	    }
1015	}
