1017	bool ProjectAutosave::save_now()
1018	{
1019	    try {
1020	        adopt_project();
1021	        settle(true); // A failed older write can be retried from the live model.
1022	        m_store->ensure_durable_head();
1023	        observe_document_change();
1024	        if (m_plater.model().objects.empty() && m_store->head_id().empty() &&
1025	            m_persistence.document().doc_revision() <= 1) {
1026	            m_error.clear();
1027	            m_state = State::Saved;
1028	            return true;
