1106	{
1107	    const bool chat = !conversation_id.empty();
1108	    std::string before_id;
1109	    std::string before_state;
1110	    std::optional<ProjectVersionStore::Materialization> materialized;
1111	    bool replacement_started = false;
1112	    bool marker_written = false;
1113	    try {
1114	        if (!save_now())
1115	            return false;
1116	        if (version_id == m_committed_head && !chat)
1117	            return true;
1118	        before_id = m_committed_head;
1119	        before_state = m_persistence.document().dump();
1120	        m_store->pin(before_id);
1121	        m_store->pin(version_id);
1122	        if (chat) {
1123	            m_store->begin_chat_restore(before_id, version_id, conversation_id);
1124	            marker_written = true;
1125	        }
1126	        if (version_id == before_id) {
1127	            // Resuming on the committed model version moves no model. The
1128	            // document transition still has to be durable before input
1129	            // moves to the resumed chat.
1130	            m_persistence.record_chat_restore(before_state, before_id, version_id, conversation_id);
1131	            if (!persist_document(true))
1132	                throw std::runtime_error(m_error);
1133	            m_store->finish_chat_restore();
1134	            m_persistence.notify_chat_restore_published();
1135	            return true;
1136	        }
1137	        materialized = m_store->materialize(version_id);
1138	        const auto selected = m_store->history();
1139	        const auto version = std::find_if(selected.begin(), selected.end(), [&version_id](const auto& item) {
1140	            return item.id == version_id;
1141	        });
1142	        if (version == selected.end())
1143	            throw std::runtime_error("selected project version is unavailable");
1144	        m_persistence.during_managed_restore([&] {
1145	            replacement_started = true;
1146	            m_plater.reset();
1147	            m_plater.take_snapshot("Restore project version", UndoRedo::SnapshotType::ProjectSeparator);
1148	            auto strategy = LoadStrategy::Restore;
1149	            if (materialized->empty)
1150	                strategy = strategy | LoadStrategy::AllowEmpty;
1151	            const auto loaded = load_managed_checkpoint(m_plater, *materialized, strategy);
1152	            if (loaded.empty() && !materialized->empty)
1153	                throw std::runtime_error("OrcaSlicer could not restore the selected model");
1154	            if (materialized->empty && !m_plater.model().objects.empty())
1155	                throw std::runtime_error("the empty project version restored geometry unexpectedly");
1156	            m_plater.set_project_filename(wxString::FromUTF8(version->source_path));
1157	            m_persistence.adopt_managed_state(before_state);
1158	            // The regions come back with the model they label.
1159	            m_persistence.document().restore_regions(materialized->regions);
1160	            const std::string kept_state = m_persistence.document().dump();
1161	            m_last_edit = Clock::now();
1162	            if (!capture(true))
1163	                throw std::runtime_error(m_error);
1164	            if (chat)
1165	                m_persistence.record_chat_restore(kept_state, before_id, version_id, conversation_id);
1166	            else
1167	                m_persistence.record_managed_restore(kept_state, before_id, version_id);
1168	            if (!persist_document(true))
1169	                throw std::runtime_error(m_error);
1170	        });
1171	        if (m_active_materialization && m_active_materialization_project == m_store->project_id()) {
1172	            try {
1173	                m_store->remove_materialization(*m_active_materialization);
1174	            } catch (const std::exception& cleanup_error) {
1175	                m_warning = std::string("Old restore workspace could not be removed: ") + cleanup_error.what();
1176	                BOOST_LOG_TRIVIAL(warning) << m_warning;
1177	            }
1178	        }
1179	        m_active_materialization = *materialized;
1180	        m_active_materialization_project = m_store->project_id();
1181	        if (chat) {
1182	            m_store->finish_chat_restore();
1183	            m_persistence.notify_chat_restore_published();
1184	        }
1185	        return true;
1186	    } catch (const std::exception& error) {
1187	        const std::string reason = error.what();
1188	        if (marker_written && !replacement_started &&
1189	            m_persistence.document().active_conversation_id() != conversation_id) {
1190	            try {
1191	                m_store->finish_chat_restore();
1192	            } catch (const std::exception& cleanup_error) {
1193	                fail(reason + "; restoration marker cleanup failed: " + cleanup_error.what());
1194	                return false;
1195	            }
1196	        }
1197	        if (replacement_started && m_store && m_store->head_id() == before_id) {
1198	            try {
1199	                const auto previous = m_store->materialize(before_id);
1200	                const auto versions = m_store->history();
1201	                const auto old = std::find_if(versions.begin(), versions.end(), [&before_id](const auto& item) {
1202	                    return item.id == before_id;
1203	                });
1204	                if (old == versions.end())
1205	                    throw std::runtime_error("previous project version is unavailable");
1206	                m_plater.reset();
1207	                m_plater.take_snapshot("Recover previous project version", UndoRedo::SnapshotType::ProjectSeparator);
1208	                auto strategy = LoadStrategy::Restore;
1209	                if (previous.empty)
1210	                    strategy = strategy | LoadStrategy::AllowEmpty;
1211	                const auto loaded = load_managed_checkpoint(m_plater, previous, strategy);
1212	                if ((loaded.empty() && !previous.empty) || (previous.empty && !m_plater.model().objects.empty()))
1213	                    throw std::runtime_error("previous project version could not be reloaded");
1214	                m_plater.set_project_filename(wxString::FromUTF8(old->source_path));
1215	                m_persistence.adopt_managed_state(before_state);
1216	                m_store->seed_from_live(m_plater.model());
1217	                m_active_materialization = previous;
1218	                m_active_materialization_project = m_store->project_id();
1219	                if (materialized)
1220	                    m_store->remove_materialization(*materialized);
1221	                if (marker_written)
1222	                    m_store->finish_chat_restore();
1223	            } catch (const std::exception& rollback_error) {
1224	                fail(reason + "; previous project also failed to reload: " + rollback_error.what());
1225	                return false;
1226	            }
1227	        }
1228	        fail(reason);
1229	        return false;
1230	    }
1231	}
